500	// ---------- apply_deposit_to_session (S16) ----------
501	
502	/**
503	 * SAGA STEP 1: Atomically reserve a deposit pool drawdown for an upcoming PaymentIntent.
504	 *
505	 * Behavior:
506	 *   1. SELECT FOR UPDATE on `projects.deposit_pool_cents_available`.
507	 *   2. Verify available >= draw_cents. RAISE EXCEPTION if not.
508	 *   3. Decrement available, increment applied.
509	 *   4. INSERT into `project_deposit_transactions` with status='pending_apply'.
510	 *   5. Return the transaction id.
511	 *
512	 * Caller flow: call this BEFORE stripe.paymentIntents.create(). Pass the returned
513	 * transaction_id in the PaymentIntent metadata. The webhook handler then calls:
514	 *   - confirm_deposit_application(txn_id) on payment_intent.succeeded
515	 *   - rollback_deposit_application(txn_id) on payment_intent.payment_failed | canceled
516	 *
517	 * If the caller fails to create the PaymentIntent, they MUST call rollback explicitly.
518	 * A reaper cron should sweep `pending_apply` rows older than 30 minutes and roll them back.
519	 */
520	export interface ApplyDepositToSessionArgs {
521	  projectId: string;
522	  sessionId: string;
523	  drawCents: CentsAmount;
524	  idempotencyKey: InkosIdempotencyKey;          // dedupe on PaymentIntent retries
525	}
526	export type ApplyDepositToSessionResult = {
527	  transaction_id: string;
528	  pool_in_cents: CentsAmount;
529	  pool_applied_cents: CentsAmount;
530	  pool_available_cents: CentsAmount;
531	};
532	
533	// ---------- confirm_deposit_application (S16) ----------
534	
535	/**
536	 * SAGA STEP 2 (success path): Mark a pending_apply transaction as applied.
537	 * Called from the webhook handler on payment_intent.succeeded.
538	 *
539	 * Idempotent — re-running on an already-confirmed txn is a no-op.
540	 * RAISE EXCEPTION if txn was already rolled_back or released.
541	 */
542	export interface ConfirmDepositApplicationArgs {
543	  transactionId: string;
544	  paymentIntentId: string;                      // for cross-reference
545	}
546	export type ConfirmDepositApplicationResult = {
547	  transaction_id: string;
548	  status: 'applied' | 'already_applied';
549	};
550	
551	// ---------- rollback_deposit_application (S16) ----------
552	
553	/**
554	 * SAGA STEP 2 (failure path): Roll back a pending_apply transaction.
555	 * Called from the webhook handler on payment_intent.payment_failed | canceled,
556	 * OR by the reaper cron after 30-min timeout.
557	 *
558	 * Behavior:
559	 *   1. SELECT FOR UPDATE on the txn + parent project.
560	 *   2. Re-increment available, decrement applied.
561	 *   3. Mark txn status='rolled_back', set rolled_back_at + reason.
562	 *
563	 * Idempotent — re-running on an already-rolled-back txn is a no-op.
564	 * RAISE EXCEPTION if txn is already 'applied' (cannot rollback a confirmed txn —
565	 * issue a refund instead via release_deposit_from_session).
566	 */
567	export interface RollbackDepositApplicationArgs {
568	  transactionId: string;
569	  reason: 'payment_failed' | 'payment_canceled' | 'reaper_timeout' | 'manual';
570	}
571	export type RollbackDepositApplicationResult = {
572	  transaction_id: string;
573	  status: 'rolled_back' | 'already_rolled_back';
574	  pool_available_cents: CentsAmount;
575	};
576	
577	// ---------- release_deposit_from_session (S16) ----------
578	
579	/**
580	 * Refund path: re-credit a previously-applied deposit drawdown back to the pool.
